//   y_screen = y + 0.3 * z   (3D depth effect)
let r = 2.2
let k = 0.5 // vertical drop per radian
let n-turns = 4.5
let n-segs = 200
let proj-x = (x, z) => x
let proj-y = (y, z) => y + 0.3 * z

// Draw the helix - BACK portion (dashed) drawn first
let last = (1.0, 0.0)
let was-front = true
for i in range(n-segs + 1) {
  let t = i / n-segs * n-turns * 2 * calc.pi
  let x = r * calc.cos(t)
  let y = r * calc.sin(t)
  let z = -k * t
  let sx = proj-x(x, z)
  let sy = proj-y(y, z)

  // Determine if this segment is "front" (y > 0) or "back" (y < 0)
  let is-front = y > 0

