    if not is-front {
      // Draw back segments as dashed
      line(last, (sx, sy), stroke: (dash: "dotted", width: 1.0pt))
    } else if not was-front {
      // Transition: draw solid from now on
      line(last, (sx, sy), stroke: 1.4pt)
