#import "@preview/cetz:0.5.2"

#set page(width: 1080pt, height: 1080pt, margin: 60pt)

#set text(font: "New Computer Modern", size: 20pt)

#set par(justify: true, leading: 0.7em)

A string of linear mass density $mu$ and tension $T$ is fixed at one end and
attached at the other end to a *light* ring of mass $m$ that can slide
freely along a *vertical* frictionless rod. A transverse wave pulse travels
along the string toward the ring, as shown.

#v(8pt)

*Which diagram correctly shows what happens to the pulse after it reaches
the ring?*

#v(8pt)

// === Setup diagram ===
#align(center)[
  #cetz.canvas({
    import cetz.draw: *
    set-style(stroke: black, fill: black, stroke-width: 1.4pt)

    // Horizontal string
    let y-string = 0.0
    let L = 4.0
    line((-L, y-string), (L, y-string), stroke: 1.4pt)

    // Fixed wall on the left (hashed)
    let x-wall = -L
    for dy in range(-7) {
      let yy = -0.4 + dy * 0.18
      line((x-wall - 0.35, y-string + yy), (x-wall, y-string + yy + 0.45), stroke: 0.8pt)
    }
    line((x-wall, y-string - 0.5), (x-wall, y-string + 0.5), stroke: 2.0pt)
    content((x-wall - 0.6, y-string - 0.6), text(size: 14pt)[fixed])

    // Vertical rod on the right
    line((L, y-string - 1.2), (L, y-string + 1.2), stroke: 1.6pt)
    // Hash marks on rod (showing it's a guide)
    for dy in range(-3) {
      let yy = -0.9 + dy * 0.5
      line((L - 0.1, y-string + yy), (L + 0.1, y-string + yy), stroke: 1.2pt)
    }
    content((L + 0.5, y-string + 1.3), text(size: 14pt)[rod])

    // Ring at x = L
    circle((L, y-string), radius: 0.25, stroke: 1.6pt, fill: white)
    // Small mass below ring
    content((L + 0.45, y-string - 0.1), text(size: 16pt)[$m$])

    // Incoming pulse: bump going up
    let pulse-x = -1.5
    let A = 0.6
    let w = 0.6
    // Draw a smooth bump using bezier-like approach
    let n = 30
    let last = (-L, y-string)
    for i in range(n + 1) {
      let xx = pulse-x - w + i / n * (2 * w)
      let bump = A * calc.exp(-((xx - pulse-x) / (w / 2)) ^ 2)
      if i > 0 {
        line(last, (xx, y-string + bump), stroke: 1.4pt)
      }
      last = (xx, y-string + bump)
    }
    // Arrow showing direction of travel
    line((pulse-x - 1.0, y-string - 0.6), (pulse-x - 0.1, y-string - 0.6),
      mark: (end: "stealth", scale: 0.9), stroke: 1.2pt)
    content((pulse-x - 1.4, y-string - 0.85), text(size: 14pt)[pulse])
  })
]

#v(10pt)

