// === Setup diagram ===
#align(center)[
  #cetz.canvas({
    import cetz.draw: *
    set-style(stroke: black, fill: black, stroke-width: 1.4pt)

    // x-axis (straight string at equilibrium)
    line((-5.0, 0), (5.0, 0), stroke: (dash: "dashed", paint: gray))

    // String snapshot (a sine wave: y = A sin(k(x - x0)))
    let A = 1.0
    let wavelength = 10.0
    let k = 2 * calc.pi / wavelength
    // Pick x0 so that P (at x_P = 0) has y=0, positive slope => sin(-k*x0) = 0
    // sin(-k*x0)=0 means k*x0 = n*pi. For positive slope at x=0:
    // derivative dy/dx = -k A cos(k(x - x0)) => at x=0: -k A cos(-k x0)
    // For positive slope: cos(-k x0) < 0 => k x0 = pi/2 (mod pi)
    let x0 = 0.0  // y(x) = A sin(k x), at x=0 slope is +kA > 0 ✓
    let x-min = -5.0
    let x-max = 5.0
    let n = 100
    let last = (x-min, 0)
    for i in range(n + 1) {
      let x = x-min + i / n * (x-max - x-min)
      let y = A * calc.sin(k * (x - x0))
      if i > 0 {
        line(last, (x, y), stroke: 1.6pt)
      }
      last = (x, y)
