    line((-5.0, 0), (5.0, 0), stroke: (dash: "dashed", paint: gray))

    // Snapshot 1 (solid, t=0)
    let A = 1.0
    let wavelength = 10.0
    let k = 2 * calc.pi / wavelength
    let phase1 = 0.0
    let x-min = -5.0
    let x-max = 5.0
    let n = 100
    let last = (x-min, 0)
    for i in range(n + 1) {
      let x = x-min + i / n * (x-max - x-min)
      let y = A * calc.sin(k * x - phase1)
      if i > 0 {
        line(last, (x, y), stroke: 1.6pt)
      }
      last = (x, y)
    }

    // Snapshot 2 (dashed, at t=T, shifted right by 0.5)
    let phase2 = k * 0.5
    let last2 = (x-min, 0)
    for i in range(n + 1) {
